def validate_edad(edad):
    if edad is None: return {"status":"review","code":"MISSING"}
    if not isinstance(edad, int): return {"status":"reject","code":"BAD_TYPE"}
    if edad < 0 or edad > 120: return {"status":"reject","code":"OUT_OF_RANGE"}
    if edad < 18: return {"status":"review","code":"NEEDS_REVIEW"}
    return {"status":"accept","code":"OK"}

def check_region(r):
    if r is None:
        return "review"
    if r not in ALLOWED:
        return "review"
    return "accept"

def tipo_doc_len(tipo, numero):
    if tipo is None or numero is None: return {"status":"review","code":"MISSING"}
    if tipo not in ALLOWED_DOC: return {"status":"review","code":"NOT_IN_ALLOWLIST"}
    if len(str(numero)) != DOC_LEN[tipo]: return {"status":"reject","code":"OUT_OF_RANGE"}
    return {"status":"accept","code":"OK"}

TABLE = {"OK":"accept", "MISSING":"review", "OUT_OF_RANGE":"reject"}
